    return 0;
}'
  }],
  exercises: [{
    id: 'ex-c13-1',
    title: 'Generic Map Function',
    instructions: 'Write a function `map` that takes an integer array, its size, and a function pointer `int (*f)(int)`, and returns a new dynamically allocated array where each element is f(original).',
    initialCode: '#include <stdio.h>
#include <stdlib.h>

int* map(int *arr, int size, int (*f)(int)) {
    // allocate result array
    // apply f to each element
}

int square(int x) { return x * x; }

int main() {
    int arr[] = {1,2,3,4};
    int *result = map(arr, 4, square);
    for (int i=0;i<4;i++) printf("%d ", result[i]);
    free(result);
    return 0;
}',
    solution: '#include <stdio.h>
#include <stdlib.h>

int* map(int *arr, int size, int (*f)(int)) {
    int *res = (int*)malloc(size * sizeof(int));
    if (!res) return NULL;
    for (int i = 0; i < size; i++) res[i] = f(arr[i]);
    return res;
}

int square(int x) { return x * x; }

int main() {
    int arr[] = {1,2,3,4};
    int *result = map(arr, 4, square);
    for (int i=0;i<4;i++) printf("%d ", result[i]);
    free(result);
    return 0;
}',
