    for (int i = 0; i < 5; i++) {
        printf("%d ", numbers[i]);
    }
    return 0;
}' },
            { type: 'heading', content: 'Strings as Character Arrays' },
            { type: 'code', content: `char greeting[6] = {'H','e','l','l','o','\0'};
